#!/usr/bin/env python3
"""Final check: download the report as Excel or JSON, and show why a catch rate is 0.
Excel sheets: Summary, By source, Wrong fields (with who flagged each and whether it was caught), False alarms, Extractors, Reviewers, Not scored.
The download recalculates from the uploaded file, so it always matches the screen, and it never records anything. Each source also shows
how many field-level reviewer flags were found, and when none are found the catch-rate tile says so.
Run from the repo root. Safe to run twice."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'frontend/src/components/enh/FinalCheck.tsx': '', 'backend/app/services/quality_export.py': ''}
MOD = {'backend/app/api/v1/routes/quality.py': [('# ─── Final records checked against the extractor and the reviewers ─────────────────\n\n@router.post("/answer-key")\nasync def answer_key(\n    file: UploadFile = File(...), apply: bool = Form(False), project_id: str = Form(""), source_id: str = Form(""), ignore: str = Form("retrieved_at"),\n    db: Session = Depends(get_db), user: User = Depends(get_current_user),\n):', '# ─── Final records checked against the extractor and the reviewers ─────────────────\n\ndef _json_dumps(o) -> bytes:\n    import json as _j\n    return _j.dumps(o, ensure_ascii=False, indent=2, default=str).encode("utf-8")\n\n\n@router.post("/answer-key")\nasync def answer_key(\n    file: UploadFile = File(...), apply: bool = Form(False), project_id: str = Form(""), source_id: str = Form(""), ignore: str = Form("retrieved_at"), export: str = Form(""),\n    db: Session = Depends(get_db), user: User = Depends(get_current_user),\n):'), ('    rev_tot: dict = {}\n    todo: list = []  # (record, row) pairs to write as audits\n    T = {"fields": 0, "wrong": 0, "cosmetic": 0, "caught": 0, "escaped": 0, "false_alarms": 0, "sources": 0, "records": 0}\n\n    for name, final_recs in key.items():', '    rev_tot: dict = {}\n    todo: list = []  # (record, row) pairs to write as audits\n    T = {"fields": 0, "wrong": 0, "cosmetic": 0, "caught": 0, "escaped": 0, "false_alarms": 0, "reviewer_flags": 0, "sources": 0, "records": 0}\n\n    for name, final_recs in key.items():'), ('        ex_name = uname(s.assigned_extractor_id) if s.assigned_extractor_id else "Unassigned"\n        sd = {"source_id": s.id, "name": s.name, "extractor": ex_name, "reviewers": sorted(uname(u) for u in peers),\n              "fields": 0, "wrong": 0, "cosmetic": 0, "caught": 0, "escaped": 0, "false_alarms": 0, "wrong_fields": [], "false_alarm_fields": [], "records": [],\n              "key_records_unmatched": [ak.record_name(final_recs[i]) or f"record {i + 1}" for i in miss_final],\n              "extractor_records_unmatched": [ak.record_name(recs[j].extracted_fields or {}, recs[j].canonical_name) or f"record {j + 1}" for j in miss_ext]}', '        ex_name = uname(s.assigned_extractor_id) if s.assigned_extractor_id else "Unassigned"\n        sd = {"source_id": s.id, "name": s.name, "extractor": ex_name, "reviewers": sorted(uname(u) for u in peers),\n              "fields": 0, "wrong": 0, "cosmetic": 0, "caught": 0, "escaped": 0, "false_alarms": 0, "reviewer_flags": len(flags), "wrong_fields": [], "false_alarm_fields": [], "records": [],\n              "key_records_unmatched": [ak.record_name(final_recs[i]) or f"record {i + 1}" for i in miss_final],\n              "extractor_records_unmatched": [ak.record_name(recs[j].extracted_fields or {}, recs[j].canonical_name) or f"record {j + 1}" for j in miss_ext]}'), ('        e = ext_tot.setdefault(s.assigned_extractor_id or "-", {"name": ex_name, "fields": 0, "wrong": 0, "sources": 0})\n        e["fields"] += sd["fields"]; e["wrong"] += sd["wrong"]; e["sources"] += 1\n        for k in ("fields", "wrong", "cosmetic", "caught", "escaped", "false_alarms"):\n            T[k] += sd[k]\n        T["sources"] += 1', '        e = ext_tot.setdefault(s.assigned_extractor_id or "-", {"name": ex_name, "fields": 0, "wrong": 0, "sources": 0})\n        e["fields"] += sd["fields"]; e["wrong"] += sd["wrong"]; e["sources"] += 1\n        for k in ("fields", "wrong", "cosmetic", "caught", "escaped", "false_alarms", "reviewer_flags"):\n            T[k] += sd[k]\n        T["sources"] += 1'), ('        result["mode"] = "applied"\n        result["applied"] = {"written": written, "already_recorded": already, "skipped": skipped}\n    return result\n', '        result["mode"] = "applied"\n        result["applied"] = {"written": written, "already_recorded": already, "skipped": skipped}\n    if export in ("xlsx", "json"):\n        from fastapi.responses import Response\n        from app.services import quality_export as qx\n        stamp = enh.now_utc().strftime("%Y%m%d")\n        if export == "json":\n            return Response(content=_json_dumps(result), media_type="application/json", headers={"Content-Disposition": f\'attachment; filename="final_check_{stamp}.json"\'})\n        return Response(content=qx.final_check_xlsx(result, {"generated": stamp}), media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",\n                        headers={"Content-Disposition": f\'attachment; filename="final_check_{stamp}.xlsx"\'})\n    return result\n')], 'frontend/src/api/client.ts': [("    return api.post('/quality/answer-key', fd, { headers: { 'Content-Type': 'multipart/form-data' }, timeout: 300000 }).then(r => r.data)\n  },\n  deleteAudit: (id: string) => api.delete(`/quality/audits/${id}`).then(r => r.data),\n  sources: (projectId?: string) => api.get('/quality/sources', { params: { project_id: projectId || undefined } }).then(r => r.data),", "    return api.post('/quality/answer-key', fd, { headers: { 'Content-Type': 'multipart/form-data' }, timeout: 300000 }).then(r => r.data)\n  },\n  answerKeyDownload: async (file: File, o: { format: 'xlsx' | 'json'; apply?: boolean; projectId?: string; sourceId?: string }) => {\n    const fd = new FormData()\n    fd.append('file', file)\n    fd.append('apply', 'false')\n    fd.append('export', o.format)\n    if (o.projectId) fd.append('project_id', o.projectId)\n    if (o.sourceId) fd.append('source_id', o.sourceId)\n    const r = await api.post('/quality/answer-key', fd, { headers: { 'Content-Type': 'multipart/form-data' }, timeout: 300000, responseType: 'blob' })\n    const url = URL.createObjectURL(new Blob([r.data]))\n    const a = document.createElement('a')\n    a.href = url\n    a.download = `final_check_${new Date().toISOString().slice(0, 10).replace(/-/g, '')}.${o.format}`\n    a.click()\n    URL.revokeObjectURL(url)\n  },\n  deleteAudit: (id: string) => api.delete(`/quality/audits/${id}`).then(r => r.data),\n  sources: (projectId?: string) => api.get('/quality/sources', { params: { project_id: projectId || undefined } }).then(r => r.data),")]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t: continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
